{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Integrative, whole-person care</title>
  <meta name="description" content="Clinical, compassionate integrative medicine blending lifestyle, targeted testing, and personalized plans. Located in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <meta name="theme-color" content="#f6fbf9">
</head>
<body class="site-root">
  <svg class="site-pattern" aria-hidden="true" focusable="false">
    <use href="assets/img/pattern.svg#bg" />
  </svg>
  <header class="topbar">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <button class="nav-toggle" aria-expanded="false" aria-controls="navlist">Menu</button>
        <ul id="navlist">
          <li><a href="services.html">Care</a></li>
          <li><a href="conditions.html">Concerns</a></li>
          <li><a href="approach.html">Method</a></li>
          <li><a href="pricing.html">Fees</a></li>
          <li><a href="about.html">Our Story</a></li>
          <li><a href="book.html">Schedule</a></li>
          <li><a href="contact.html">Reach</a></li>
        </ul>
      </nav>
      <div class="contact-quick">
        <a class="phone" href="tel:{{PHONE}}">{{PHONE}}</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero wrap">
      <div class="hero-content">
        <h1 class="eyebrow">Whole-person care in {{CITY}}, {{STATE}}</h1>
        <h2>{{TAGLINE}}</h2>
        <p class="lead">We blend evidence-informed medicine, lifestyle coaching, and thoughtful testing to support sustainable health. Appointments with {{PRACTITIONER_NAME}}, {{CREDENTIALS}}.</p>
        <div class="hero-actions">
          <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="muted" href="about.html">Meet the team</a>
        </div>
      </div>
      <div class="hero-visual" aria-hidden="true">
        <div class="visual-card">
          <svg viewBox="0 0 200 200" class="blob" xmlns="http://www.w3.org/2000/svg">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#8fd3a6" />
                <stop offset="1" stop-color="#5bb6b1" />
              </linearGradient>
            </defs>
            <path fill="url(#g1)" d="M41.6,-56.9C54.3,-45,66.4,-34.1,72.8,-19.7C79.3,-5.3,80.1,12.6,73.9,27.4C67.6,42.1,54.3,53.7,38.6,61.4C22.9,69.1,4.9,73,-10.6,69.6C-26.1,66.2,-39.1,55.4,-50.7,42.6C-62.2,29.9,-72.5,15,-72.2,1.3C-71.8,-12.4,-60.7,-24.7,-49.1,-37.2C-37.6,-49.7,-25.4,-62.5,-10.7,-67.7C4,-72.9,20,-70.8,36.4,-63.2C52.8,-55.7,69.6,-42.3,41.6,-56.9Z" transform="translate(100 100)"/>
          </svg>
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section id="myth-truth" class="wrap myth">
      <h3>Common beliefs — examined</h3>
      <div class="cols">
        <aside class="col myth-list">
          <h4>Myths people often hear</h4>
          <ul>
            <li>Myth: Holistic means alternative instead of medical care.</li>
            <li>Myth: More supplements always equals better results.</li>
            <li>Myth: Testing will always show a definitive answer.</li>
          </ul>
        </aside>
        <div class="col truth-list">
          <h4>Truths we center</h4>
          <ul>
            <li>Truth: Integrative care pairs evidence-based medicine with lifestyle and mind-body support.</li>
            <li>Truth: Individualized, measured interventions are safer and often more effective than blanket approaches.</li>
            <li>Truth: Tests are tools that inform a plan — they rarely offer one-size-fits-all certainty.</li>
          </ul>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section id="pillars" class="wrap pillars">
      <h3>Core pillars of our approach</h3>
      <p class="sub">A balanced plan considers body systems, rhythms, and context.</p>
      <div class="grid">
        <article class="card">
          <h4>Nutrition & Metabolic Support</h4>
          <p>Personalized guidance that emphasizes whole foods, circadian timing, and blood-sugar balance.</p>
        </article>
        <article class="card">
          <h4>Mind–Body Integration</h4>
          <p>Evidence-based stress reduction and mental health strategies integrated into care plans.</p>
        </article>
        <article class="card">
          <h4>Movement & Recovery</h4>
          <p>Practical activity plans that promote resilience and joint health without overprescription.</p>
        </article>
        <article class="card">
          <h4>Rest, Rhythm & Sleep</h4>
          <p>Behavioral tools and environment adjustments to reclaim restorative sleep, a cornerstone of healing.</p>
        </article>
      </div>
    </section>

    <!-- CASE NOTES -->
    <section id="case-notes" class="wrap cases">
      <header>
        <h3>Clinical snapshots (de-identified)</h3>
        <p class="muted">Short examples of integrated plans — not guarantees. Outcomes vary by individual.</p>
      </header>
      <div class="case-grid">
        <figure>
          <figcaption>Case: Persistent fatigue</figcaption>
          <p>Approach: Detailed history, labs to rule out deficiency or thyroid change, sleep optimization, graded activity, nutrition recalibration. Follow-up and adjustments over 12 weeks.</p>
        </figure>
        <figure>
          <figcaption>Case: Digestive discomfort</figcaption>
          <p>Approach: Symptom mapping, elimination diet trial, targeted stool testing if needed, mindful eating practices, and referral when structural disease is suspected.</p>
        </figure>
        <figure>
          <figcaption>Case: Chronic stress & insomnia</figcaption>
          <p>Approach: Cognitive-behavioral strategies, brief medication review, relaxation practice, circadian reinforcement, and optional salivary cortisol education.</p>
        </figure>
      </div>
    </section>

    <!-- FAQ -->
    <section id="faq" class="wrap faq">
      <h3>Questions we hear</h3>
      <div class="qa">
        <button class="q">Do you offer lab testing?</button>
        <div class="a">Yes. We order or recommend targeted tests when clinically appropriate and review results in context. Labs are discussed as educational tools rather than absolute answers.</div>
        <button class="q">Will I be prescribed supplements?</button>
        <div class="a">Supplements may be suggested selectively and monitored. We prioritize dietary and lifestyle changes first where possible.</div>
        <button class="q">Is this a replacement for specialty care?</button>
        <div class="a">No. We coordinate with specialists and refer when necessary. Our role is to integrate and support whole-person health alongside conventional care.</div>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="wrap cta-section">
      <div class="cta-inner">
        <h3>Ready to begin thoughtful care?</h3>
        <p>Schedule an intake to explore a personalized plan. We prioritize measurable, mindful changes over quick fixes.</p>
        <div class="actions">
          <a class="primary large" href="{{PRIMARY_CTA_URL}}">Book an appointment</a>
          <a class="outline" href="contact.html">Questions? Email us — {{EMAIL}}</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-foot">
    <div class="wrap foot-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a>
      </div>
      <div>
        <nav>
          <a href="about.html">About</a> • <a href="services.html">Services</a> • <a href="privacy.html">Privacy</a>
        </nav>
      </div>
      <div>
        <small>Practitioner: {{PRACTITIONER_NAME}}, {{CREDENTIALS}}</small>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
