{"path":"assets/css/styles.css","content":"/* Core styling for the integrative clinic template */
:root{
  --bg:#f6fbf9;
  --card:#ffffffcc;
  --accent1:#5bb6b1;
  --accent2:#8fd3a6;
  --muted:#6b6f76;
  --glass:rgba(255,255,255,0.75);
  --radius:14px;
  --max:1100px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  background:linear-gradient(180deg,var(--bg),#eef8f4 40%);
  color:#13323a;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
}
.site-pattern{position:fixed;inset:0;pointer-events:none;width:100%;height:100%;opacity:0.12}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.topbar{backdrop-filter:blur(6px);background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.45));border-bottom:1px solid rgba(0,0,0,0.04)}
.topbar .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--accent1);text-decoration:none}
.main-nav{margin-left:auto}
.nav-toggle{display:none}
.main-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:12px}
.main-nav a{color:#123; text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a:hover{background:rgba(0,0,0,0.04)}
.contact-quick{display:flex;gap:10px;align-items:center;margin-left:12px}
.contact-quick .cta{background:var(--accent1);color:white;padding:8px 12px;border-radius:10px;text-decoration:none}
.contact-quick .phone{color:var(--muted);text-decoration:none}

.hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center;padding-top:36px;padding-bottom:36px}
.hero .eyebrow{font-size:14px;color:var(--muted);margin:0}
.hero h2{margin:6px 0 12px;font-size:32px}
.hero .lead{color:#2b4a4a;max-width:58ch}
.hero-actions{display:flex;gap:12px}
.primary{background:linear-gradient(90deg,var(--accent2),var(--accent1));color:white;padding:10px 16px;border-radius:12px;text-decoration:none}
.muted{color:var(--muted);text-decoration:none;padding:10px 16px}
.hero-visual .visual-card{background:var(--glass);border-radius:20px;padding:24px;display:flex;align-items:center;justify-content:center;box-shadow:0 8px 30px rgba(12,24,20,0.06)}
.blob{width:220px;height:220px}

.myth{background:transparent;padding:22px 0}
.myth .cols{display:flex;gap:24px}
.col h4{margin-top:0}
.myth-list{flex:1}
.truth-list{flex:1}
.myth ul,.truth-list ul{margin:0;padding-left:18px;color:var(--muted)}

.pillars{padding:26px 0}
.pillars .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:14px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(12,24,20,0.04)}
.card h4{margin:0 0 8px}

.cases{padding:26px 0}
.case-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.case-grid figure{background:#fff;border-radius:12px;padding:16px;box-shadow:0 6px 18px rgba(9,20,18,0.04)}
.case-grid figcaption{font-weight:600;margin-bottom:6px}

.faq{padding:20px 0}
.qa{max-width:820px}
.q{width:100%;text-align:left;padding:12px 16px;border:1px solid rgba(0,0,0,0.06);background:white;border-radius:10px;margin-top:10px}
.a{padding:12px 16px;color:var(--muted);display:none;border-left:3px solid var(--accent1);background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);border-radius:0 10px 10px 10px}

.cta-section{margin:34px 0;padding:28px;background:linear-gradient(90deg,rgba(139,212,186,0.16),rgba(91,182,177,0.06));border-radius:16px}
.cta-inner{display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.primary.large{padding:14px 22px;font-size:16px}
.outline{padding:12px 18px;border-radius:12px;border:1px solid rgba(0,0,0,0.06);text-decoration:none;color:var(--muted)}

.site-foot{padding:22px 0;margin-top:28px;border-top:1px solid rgba(0,0,0,0.04);background:transparent}
.foot-grid{display:flex;justify-content:space-between;align-items:center}

/* Responsive */
@media (max-width:900px){
  .hero{grid-template-columns:1fr;}
  .pillars .grid{grid-template-columns:repeat(2,1fr)}
  .case-grid{grid-template-columns:1fr}
  .main-nav ul{display:none;position:absolute;right:18px;top:64px;background:white;padding:10px;border-radius:10px;box-shadow:0 8px 30px rgba(0,0,0,0.08)}
  .nav-toggle{display:inline-block}
}
@media (max-width:520px){
  .pillars .grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var btn=document.querySelector('.nav-toggle');
  var nav=document.getElementById('navlist');
  if(btn){
    btn.addEventListener('click',function(){
      var expanded=this.getAttribute('aria-expanded')==='true';
      this.setAttribute('aria-expanded',!expanded);
      if(nav.style.display==='block'){nav.style.display=''} else {nav.style.display='block'}
    });
  }

  // FAQ accordion
  document.querySelectorAll('.qa .q').forEach(function(q){
    q.addEventListener('click',function(){
      var next=this.nextElementSibling;
      var open=next.style.display==='block';
      // close others
      document.querySelectorAll('.qa .a').forEach(function(a){a.style.display='none'});
      if(!open) next.style.display='block';
    });
  });

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var id=this.getAttribute('href').slice(1);
      var el=document.getElementById(id);
      if(el){e.preventDefault();el.scrollIntoView({behavior:'smooth',block:'start'})}
    });
  });

})();
"} 
